"""Register the stack's object stores with Unity Catalog (generated by trestle).

Each `location` line in /storage.txt becomes a storage credential (the store's IAM role) and
an external location over its bucket; a `catalog` line becomes a catalog whose managed
storage sits under the first location. Objects that already exist are left alone, so this
runs on every `up`. It then stays up, healthy, so `docker compose up --wait` returns only once
storage is registered.
"""

import json
import pathlib
import signal
import sys
import urllib.error
import urllib.request

API = "http://unitycatalog:8080/api/2.1/unity-catalog"
READY = pathlib.Path("/tmp/registered")


def call(method: str, path: str, body: dict | None = None) -> int:
    request = urllib.request.Request(
        API + path,
        method=method,
        data=None if body is None else json.dumps(body).encode(),
        headers={"Content-Type": "application/json"},
    )
    try:
        with urllib.request.urlopen(request) as response:
            return response.status
    except urllib.error.HTTPError as err:
        if method == "GET" and err.code == 404:
            return 404
        detail = err.read().decode(errors="replace")
        sys.exit(f"{method} {path}: HTTP {err.code} {detail}")


def ensure(collection: str, name: str, body: dict) -> None:
    if call("GET", f"/{collection}/{name}") == 404:
        call("POST", f"/{collection}", {"name": name, **body})
        print(f"created {collection}/{name}")
    else:
        print(f"exists  {collection}/{name}")


def main() -> None:
    # Compose logs aren't a TTY, and the process never exits to flush them.
    sys.stdout.reconfigure(line_buffering=True)
    comment = {"comment": "Registered by trestle"}
    roots: list[str] = []
    with open("/storage.txt") as lines:
        for line in lines:
            parts = line.split()
            if not parts or parts[0].startswith("#"):
                continue
            kind, *fields = parts
            if kind == "location":
                name, url, credential, role_arn = fields
                ensure(
                    "credentials",
                    credential,
                    {"purpose": "STORAGE", "aws_iam_role": {"role_arn": role_arn}, **comment},
                )
                ensure(
                    "external-locations",
                    name,
                    {"url": url, "credential_name": credential, **comment},
                )
                roots.append(url)
            elif kind == "catalog":
                (name,) = fields
                if not roots:
                    sys.exit(f"catalog {name}: no external location to put its storage under")
                ensure("catalogs", name, {"storage_root": f"{roots[0]}/{name}", **comment})
    print("Unity Catalog storage registered.")
    READY.touch()
    signal.pause()


if __name__ == "__main__":
    main()
